#!/usr/bin/env node
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    VaultV29Category, VaultV29Status, VaultV29Upgrade, VaultV29EnemyUpgrade, VaultV29Tree, VAULT_V29_VERIFIED, VAULT_V29_PROVENANCE, VAULT_V29_HARMONY (+2 more)
 * depends    —
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/**
 * Read the v29 vault workbook into a dataset the package can compare against later.
 *
 *   node scripts/build-vault-v29.mjs           # report what it found
 *   node scripts/build-vault-v29.mjs --write   # emit the generated module
 *
 * ## Why this is separate from the vault the package already ships
 *
 * v29 reworked the vault into something structurally different. The shipped tree
 * (`src/data/vault/tree.ts`) is a graph: every node has `parents`, and a node is unreachable until
 * its prerequisites are bought. v29 removes prerequisites entirely and replaces them with flat
 * CATEGORIES, each with a one-time unlock cost, holding upgrades that price per level.
 *
 * So this is not an edit to the existing data — the two describe different systems, and the old one
 * stays correct until v29 is the version in players' hands.
 *
 * ## This data is not verified
 *
 * It comes from a developer-supplied workbook ahead of the release, not from the game. Every entry
 * is marked `verified: false`, and nothing in the package computes with it. It exists so that when
 * the v29 build can be read directly, there is something precise to check the extraction against —
 * which is the whole reason to record it now rather than after.
 *
 * ## What the colours mean, and why they are read
 *
 * The Power sheet carries a legend in its first column: red for a workshop upgrade the rework is
 * NOT including, yellow for one with a clarification, green for one being added in this update.
 * That status is held in the cell FILL and nowhere else — `sheet_to_json` drops it silently, which
 * would turn "we are not including this" into an ordinary row indistinguishable from the rest.
 *
 * Anything this cannot classify is REPORTED, never dropped. A vault extract that quietly skips a
 * row it did not understand produces a smaller, plausible dataset and no evidence that it did.
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import XLSX from 'xlsx'

const PACKAGE_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const WORKBOOK = path.join(PACKAGE_ROOT, 'data', 'vault-v29', 'new-vault-values.xlsx')
const OUT = path.join(PACKAGE_ROOT, 'src', 'data', 'generated', 'vault-v29.generated.ts')
const WRITE = process.argv.includes('--write')

/** Fill colour -> what the Power legend says it means. */
const STATUS_BY_FILL = {
  F4CCCC: 'excluded',
  FFF2CC: 'clarified',
  D9EAD3: 'added',
}

const problems = []

function sheet(book, name) {
  const ws = book.Sheets[name]
  if (!ws) throw new Error(`workbook has no "${name}" sheet`)
  return ws
}

/** The category legend: name in column A, unlock cost in column B. */
function categories(rows) {
  const out = []
  for (const row of rows) {
    const name = row[0]
    const cost = row[1]
    if (typeof name !== 'string' || !name.trim()) continue
    /* The Power sheet's legend rows sit in the same columns; they explain colours, not costs. */
    if (typeof cost === 'string' && cost.length > 30) continue
    out.push({
      name: name.trim(),
      unlockCost: cost === 'Auto unlocked' ? 0 : (typeof cost === 'number' ? cost : null),
      autoUnlocked: cost === 'Auto unlocked',
    })
  }
  return out
}

function fillAt(ws, rowIndex, col) {
  const ref = XLSX.utils.encode_cell({ r: rowIndex, c: col })
  const cell = ws[ref]
  const rgb = cell?.s?.fgColor?.rgb
  return rgb ? STATUS_BY_FILL[String(rgb).toUpperCase()] ?? null : null
}

/**
 * Harmony and Power: a bare name in column D opens a section, and every row under it is an
 * upgrade whose per-level key costs run from column E.
 */
/**
 * Section headers do not always spell the category the same way.
 *
 * Harmony's legend says "Guardians" and its section header says "Guardian". An exact match missed
 * it, so the header was read as an upgrade and every row beneath it was filed under the PREVIOUS
 * category — a silent misattribution, since the rows still exist and still have their costs.
 */
const sectionKey = name => name.trim().toLowerCase().replace(/s$/, '')

function upgrades(ws, rows, sheetName) {
  const known = new Map(categories(rows).map(c => [sectionKey(c.name), c.name]))
  const out = []
  let section = null

  rows.forEach((row, index) => {
    const name = row[3]
    if (typeof name !== 'string' || !name.trim()) return
    const label = name.trim().replace(/^`/, '')
    const levelCosts = row.slice(4).filter(v => typeof v === 'number')

    if (known.has(sectionKey(label)) && levelCosts.length === 0) { section = known.get(sectionKey(label)); return }
    if (!section) { problems.push(`${sheetName}: "${label}" appears before any section`); return }

    out.push({
      category: section,
      name: label,
      levelCosts,
      status: fillAt(ws, index, 3),
    })
  })
  return out
}

/**
 * Enemy: column D names the enemy, column E the stat, and thirty levels follow. The enemy name
 * appears once and carries down its rows, so a blank column D continues the previous enemy.
 */
function enemyUpgrades(ws, rows) {
  const known = new Map(categories(rows).map(c => [sectionKey(c.name), c.name]))
  const out = []
  let section = null
  let enemy = null

  rows.forEach((row, index) => {
    const first = typeof row[3] === 'string' ? row[3].trim() : ''
    const stat = typeof row[4] === 'string' ? row[4].trim() : ''
    const levelCosts = row.slice(5).filter(v => typeof v === 'number')

    if (first && known.has(sectionKey(first))) { section = known.get(sectionKey(first)); enemy = null; return }
    if (!stat) return
    /* The header row numbers the levels 1..30; it is a ruler, not an upgrade. */
    if (known.has(sectionKey(stat))) { section = known.get(sectionKey(stat)); return }
    if (first) enemy = first
    if (!enemy || !section) { problems.push(`Enemy: "${stat}" has no enemy or category above it`); return }

    out.push({
      category: section,
      enemy,
      stat,
      levelCosts,
      status: fillAt(ws, index, 4),
    })
  })
  return out
}

const book = XLSX.readFile(WORKBOOK, { cellStyles: true })
const asRows = name => XLSX.utils.sheet_to_json(sheet(book, name), { header: 1, blankrows: false })

const harmonyRows = asRows('Harmony')
const powerRows = asRows('Power')
const enemyRows = asRows('Enemy')

const data = {
  harmony: { categories: categories(harmonyRows), upgrades: upgrades(sheet(book, 'Harmony'), harmonyRows, 'Harmony') },
  power: { categories: categories(powerRows), upgrades: upgrades(sheet(book, 'Power'), powerRows, 'Power') },
  enemy: { categories: categories(enemyRows), upgrades: enemyUpgrades(sheet(book, 'Enemy'), enemyRows) },
}

for (const [tree, { categories: cats, upgrades: ups }] of Object.entries(data)) {
  console.log(`${tree.padEnd(8)} ${String(cats.length).padStart(2)} categories, ${String(ups.length).padStart(3)} upgrades`)
}
const statuses = [...Object.values(data)].flatMap(t => t.upgrades).filter(u => u.status)
console.log(`\ncolour-coded rows: ${statuses.length} (${[...new Set(statuses.map(s => s.status))].join(', ')})`)

if (problems.length > 0) {
  console.error(`\n${problems.length} row(s) could not be classified:`)
  for (const line of problems) console.error(`  ${line}`)
  process.exit(1)
}

if (!WRITE) { console.log('\ndry run — re-run with --write.'); process.exit(0) }

const body = `/**
 * The v29 vault, as the developers described it before release.
 *
 * GENERATED — do not edit. Run \`npm run vault:v29\`.
 *
 * Not verified against the game. This is a developer-supplied workbook, recorded so the numbers
 * can be checked the moment a v29 build can be read; nothing in this package computes with it.
 * The shipped vault in \`src/data/vault\` still describes v28 and stays correct until v29 is the
 * version players are on.
 *
 * v29 removed prerequisites: categories unlock once, then upgrades price per level.
 */

export interface VaultV29Category {
  readonly name: string
  /** Keys to unlock the category. 0 where it is open from the start. */
  readonly unlockCost: number | null
  readonly autoUnlocked: boolean
}

/** What the workbook's colour legend says about a Power row. */
export type VaultV29Status = 'excluded' | 'clarified' | 'added'

export interface VaultV29Upgrade {
  readonly category: string
  readonly name: string
  /** Key cost per level, in order. Empty where the workbook gave none. */
  readonly levelCosts: readonly number[]
  readonly status: VaultV29Status | null
}

/**
 * An Enemy-tree row, which is named by its enemy and stat rather than by a single label.
 *
 * Deliberately not extending VaultV29Upgrade: that carries a name, and an enemy row has no
 * single name to put in it. Extending it and leaving name off does not type-check, which is the
 * type system noticing that these are two different shapes wearing one word.
 */
export interface VaultV29EnemyUpgrade {
  readonly category: string
  readonly enemy: string
  readonly stat: string
  readonly levelCosts: readonly number[]
  readonly status: VaultV29Status | null
}

export interface VaultV29Tree {
  readonly categories: readonly VaultV29Category[]
  readonly upgrades: readonly VaultV29Upgrade[]
}

/** Every entry is unverified until it is read out of a v29 build. */
export const VAULT_V29_VERIFIED = false

export const VAULT_V29_PROVENANCE = 'developer-supplied workbook, 2026-08-21, ahead of the v29 release'

export const VAULT_V29_HARMONY: VaultV29Tree = ${JSON.stringify(data.harmony, null, 2)} as const

export const VAULT_V29_POWER: VaultV29Tree = ${JSON.stringify(data.power, null, 2)} as const

export const VAULT_V29_ENEMY: {
  readonly categories: readonly VaultV29Category[]
  readonly upgrades: readonly VaultV29EnemyUpgrade[]
} = ${JSON.stringify(data.enemy, null, 2)} as const
`

fs.writeFileSync(OUT, body, 'utf8')
console.log(`\nwrote ${path.relative(PACKAGE_ROOT, OUT)}`)
